primaryQuery:
run: order_items -> {
  aggregate:
    total_sales is sale_price.sum()
    items_sold is count()
} -> {
  select:
    total_sales
    items_sold
    avg_selling_price_per_item is round(total_sales / items_sold, 4)
}

verifyQuery:
run: order_items -> {
  group_by: status
  aggregate:
    s is sale_price.sum()
    n is count()
} -> {
  aggregate:
    total_sales is s.sum()
    items_sold is n.sum()
} -> {
  select:
    total_sales
    items_sold
    avg_selling_price_per_item is round(total_sales / items_sold, 4)
}
